def _lookup(family, lg):
    tab = ES if lg == "es" else EN
    if family in tab: return tab[family]
    for prefixes, entry in (PREFIX_ES if lg == "es" else PREFIX_EN):
        if any(str(family or "").startswith(p) for p in prefixes): return entry
    return GEN_ES if lg == "es" else GEN_EN

DECIDE = {"en": "Decide per occurrence: REAL -> apply the fix steps; FALSE POSITIVE -> suppress with the exact line below (always with a reason); UNSURE -> ask the code owner and say so - never present an unconfirmed finding as a vulnerability.",
          "es": "Decide por cada ocurrencia: REAL -> aplica los pasos de corrección; FALSO POSITIVO -> suprímelo con la línea exacta de abajo (siempre con motivo); DUDOSO -> pregunta al dueño del código y dilo - nunca presentes como vulnerabilidad un hallazgo sin confirmar."}
REPORT = {"en": "Report each one as: REAL / FALSE POSITIVE / UNSURE + file:line + the evidence you checked (what you read or ran).", "es": "Reporta cada uno como: REAL / FALSO POSITIVO / DUDOSO + archivo:línea + la evidencia que comprobaste (qué leíste o ejecutaste)."}
COMMENT = {"py": "#", "rb": "#", "sh": "#", "bash": "#", "yml": "#", "yaml": "#", "toml": "#", "pl": "#", "r": "#", "tf": "#", "ps1": "#", "ex": "#", "exs": "#", "sql": "--", "lua": "--", "html": "<!--", "htm": "<!--", "md": "<!--"}


def suppression(f):
    """exact inline / ignore-file lines to mark a false positive (with a reason)."""
    loc = f.get("location") or {}; path = loc.get("file") or "."; rule = f.get("rule") or "RULE"
    ext = os.path.basename(path).rsplit(".", 1)[-1].lower() if "." in os.path.basename(path) else ""
    c = COMMENT.get(ext, "//")
    close = " -->" if c == "<!--" else ""
    return dict(inline=f"{c} pn-audit: ignore={rule} <reason: why this is safe>{close}", ignorefile=f"{path}  {rule}   # <reason>")


def for_finding(f, lang="en"):
    lg = "es" if lang == "es" else "en"
    c, real, fp = _lookup(f.get("family"), lg)
    sup = suppression(f)
    out = dict(confirm=list(c), real_if=real, false_positive_if=fp, decide=DECIDE[lg], report_as=REPORT[lg], suppress_inline=sup["inline"], suppress_file=sup["ignorefile"], needs_confirmation=f.get("status") != "confirmed")
    why = f.get("why") or f.get("needs_validation_reason")
    if why and f.get("status") != "confirmed": out["scanner_note"] = str(why)[:300]
    return out
